import DeleteOutlineRoundedIcon from '@mui/icons-material/DeleteOutlineRounded';
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Slide,
  Stack,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { TransitionProps } from '@mui/material/transitions';
import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { appColors } from '../../theme/appColors';

interface IDeletePopup {
  open: boolean;
  handleCloseDelete: (close: boolean) => void;
  onConfirm: () => Promise<void>;
  title: string;
  content: string;
}

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & {
    children: React.ReactElement<string, string>;
  },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

// eslint-disable-next-line react/no-multi-comp
const DeletePopup = ({
  open,
  handleCloseDelete,
  onConfirm,
  title,
  content,
}: IDeletePopup) => {
  const [isLoading, setIsLoading] = useState(false);
  const { t } = useTranslation(['common']);

  const onClose = () => handleCloseDelete(false);

  const handleDelete = async () => {
    setIsLoading(true);
    try {
      await onConfirm();
    } catch (error) {
      console.error('Error while deleting:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog
      PaperProps={{
        sx: {
          background:
            'linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(255,248,248,0.96) 100%)',
          border: `1px solid ${alpha('#DC2626', 0.12)}`,
          borderRadius: '8px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 420,
        },
      }}
      TransitionComponent={Transition}
      onClose={onClose}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: `linear-gradient(135deg, ${alpha('#DC2626', 0.06)} 0%, ${alpha('#FCA5A5', 0.04)} 100%)`,
            borderBottom: `1px solid ${alpha('#DC2626', 0.12)}`,
            px: 3,
            py: 2,
          }}
        >
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box
              sx={{
                alignItems: 'center',
                background:
                  'linear-gradient(135deg, #DC2626 0%, #b91c1c 100%)',
                borderRadius: '8px',
                color: appColors.white,
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
              }}
            >
              <DeleteOutlineRoundedIcon sx={{ fontSize: 18 }} />
            </Box>
            <Box>
              <Typography
                sx={{
                  color: '#142352',
                  fontSize: '1rem',
                  fontWeight: 800,
                  lineHeight: 1.2,
                }}
              >
                {title}
              </Typography>
              <Typography
                sx={{
                  color: alpha('#142352', 0.5),
                  fontSize: '0.75rem',
                  fontWeight: 500,
                }}
              >
                This action cannot be undone
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      {/* Body */}
      <DialogContent sx={{ p: 0 }}>
        <Box sx={{ px: 3, py: 3 }}>
          <Stack
            alignItems="flex-start"
            direction="row"
            spacing={1.5}
          >
            <WarningAmberRoundedIcon
              sx={{
                color: '#D97706',
                flexShrink: 0,
                fontSize: 20,
                mt: 0.1,
              }}
            />
            <Typography
              sx={{
                color: alpha('#142352', 0.75),
                fontSize: '0.9rem',
                fontWeight: 500,
                lineHeight: 1.55,
              }}
            >
              {content}
            </Typography>
          </Stack>
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ p: 0 }}>
        <Box
          sx={{
            borderTop: `1px solid ${alpha('#DC2626', 0.1)}`,
            display: 'flex',
            gap: 1.5,
            justifyContent: 'flex-end',
            px: 3,
            py: 2,
            width: '100%',
          }}
        >
          <Button
            onClick={onClose}
            sx={{
              borderColor: alpha('#142352', 0.2),
              borderRadius: '6px',
              color: '#142352',
              fontWeight: 700,
              px: 2.5,
              '&:hover': {
                background: alpha('#142352', 0.04),
                borderColor: alpha('#142352', 0.35),
              },
            }}
            variant="outlined"
          >
            {t('common:cancel')}
          </Button>

          <Button
            disabled={isLoading}
            onClick={handleDelete}
            sx={{
              background:
                'linear-gradient(135deg, #DC2626 0%, #b91c1c 100%)',
              borderRadius: '6px',
              boxShadow: `0 4px 14px ${alpha('#DC2626', 0.35)}`,
              color: appColors.white,
              fontWeight: 700,
              minWidth: 100,
              px: 3,
              '&:hover': {
                background:
                  'linear-gradient(135deg, #b91c1c 0%, #991b1b 100%)',
                boxShadow: `0 6px 18px ${alpha('#DC2626', 0.45)}`,
              },
              '&.Mui-disabled': {
                background: alpha('#DC2626', 0.35),
                color: alpha('#fff', 0.7),
              },
            }}
            variant="contained"
          >
            {isLoading ? (
              <CircularProgress
                size={16}
                sx={{ color: '#fff' }}
              />
            ) : (
              t('common:delete')
            )}
          </Button>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default DeletePopup;
