import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  TextField,
  useMediaQuery,
  FormControlLabel,
  SelectChangeEvent,
  Switch,
  FormControl,
  Select,
  OutlinedInput,
  MenuItem,
  Checkbox,
  ListItemText,
} from '@mui/material';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import {
  useNewCompanyMutation,
  useGetAllUserPrivilegesQuery,
} from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import {
  ICompanyDetailsData,
} from '../../../core/Interface/company.interface';
import dayjs from 'dayjs';
import { useMemo } from 'react';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import SearchIcon from '@mui/icons-material/Search';
import InputAdornment from '@mui/material/InputAdornment';

interface INewCompany {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: ICompanyDetailsData;
}

const NewCompany = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
}: INewCompany) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newCompany, { isLoading }] = useNewCompanyMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'category', 'company']);
  const buttonText = data ? t('common:update') : t('common:create');
  const [privilegeSearchText, setPrivilegeSearchText] = React.useState('');

  const [systemPrice, setSystemPrice] = React.useState(
    data ? data.systemPrice : 59000
  );
  const [paidAmount, setPaidAmount] = React.useState(data ? data.totalPaid : 0);
  const [balance, setBalance] = React.useState(
    data ? data.systemPrice - data.totalPaid : 59000
  );

  const { data: privileges } =
    useGetAllUserPrivilegesQuery();

  const [privilegeIds, setPrivilegeIds] = React.useState<number[]>(
    data?.companyPrivileges?.map((privilege) => privilege.id) ?? []
  );

  const [isMonthly, setIsMonthly] = React.useState(
    data ? data.isMonthly : false
  );
  const [maintenanceFee, setMaintenanceFee] = React.useState<number | string>(
    data ? data.maintenanceFee : 15000
  );

  const validateMobileNumber = (value: string) => {
    const mobileRegex = /^[0-9]+$/;
    const isMobileValid =
      (value.startsWith('0') && value.length === 10) ||
      (!value.startsWith('0') && value.length === 9);
    return isMobileValid && mobileRegex.test(value);
  };

  React.useEffect(() => {
    if (data) {
      setSystemPrice(data.systemPrice || 0);
      setPaidAmount(data.totalPaid || 0);
      setBalance((data.systemPrice || 0) - (data.totalPaid || 0));
    }
  }, [data]);

  const filteredPrivileges = useMemo(() => {
    if (!privileges?.data) return [];
    const privilegesData = privileges.data as { key: string; value: number }[];
    return privilegesData.filter((privilege) =>
      privilege.key.toLowerCase().includes(privilegeSearchText.toLowerCase())
    );
  }, [privileges, privilegeSearchText]);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      id: data?.id,
      code: data?.code ?? '',
      name: data?.name ?? '',
      isImageEnabled: data?.isImageEnabled ?? false,
      maxUsersAllowed: data?.maxUsersAllowed ?? 2,
      maxBranchAllowed: data?.maxBranchAllowed ?? 1,
      currencyCode: data?.currencyCode ?? 'Rs.',
      systemPrice: data?.systemPrice ?? 59000,
      totalPaid: data?.totalPaid ?? 0,
      balance: data ? data.systemPrice - data.totalPaid : 59000,
      maintenanceFeePaidUntil: data?.maintenanceFeePaidUntil ?? dayjs().add(1, 'month'),
      maintenanceFee: data?.maintenanceFee ?? 15000,
      isMonthly: data?.isMonthly ?? false,
      contactNo: data?.contactNo ?? '',
      contactPerson: data?.contactPerson ?? '',
      isEnabled: data?.isEnabled ?? true,
      usersCount: data?.usersCount,
      branchesCount: data?.branchesCount,
      privileges: data?.companyPrivileges?.map((item) => item.id) ?? [],
    },
    onSubmit: async (values) => {
      try {
        if (!data) {
          delete values.id;
        }

        if (!values.contactNo) {
          showErrorMessage('Contact number is required.');
          return;
        }

        if (!validateMobileNumber(values.contactNo)) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }

        if (!values.contactPerson) {
          showErrorMessage('Contact person is required.');
          return;
        }

        if (privilegeIds.length === 0) {
          showErrorMessage('At least one privilege must be selected.');
          return;
        }

        const addCompanyResponse = await newCompany(values).unwrap();
        if (!addCompanyResponse.status) {
          showErrorMessage(addCompanyResponse.message);
        } else {
          showMessage(addCompanyResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    const isEmptyOrInvalid = (value: unknown) =>
      value === '' || value === undefined || value === null;

    return !(
      formik.values.code === '' ||
      formik.values.code === undefined ||
      formik.values.name === '' ||
      formik.values.name === undefined ||
      isEmptyOrInvalid(formik.values.systemPrice) ||
      isEmptyOrInvalid(formik.values.totalPaid) ||
      isEmptyOrInvalid(formik.values.maintenanceFee) ||
      isEmptyOrInvalid(formik.values.maxUsersAllowed) ||
      isEmptyOrInvalid(formik.values.maxBranchAllowed) ||
      isEmptyOrInvalid(formik.values.currencyCode) ||
      isEmptyOrInvalid(formik.values.contactNo) ||
      isEmptyOrInvalid(formik.values.contactPerson) ||
      privilegeIds.length === 0
    );
  }, [formik, privilegeIds]);

  const handleMaintenanceFeeChange = (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const fee = parseFloat(e.target.value) || 0;
    setMaintenanceFee(fee);
    formik.setFieldValue('maintenanceFee', fee);
  };

  const handleFeeTypeChange = (isMonthlyFee: boolean) => {
    setIsMonthly(isMonthlyFee);
    formik.setFieldValue('isMonthly', isMonthlyFee);
  };

  const handleChange = (event: SelectChangeEvent<typeof privilegeIds>) => {
    const {
      target: { value },
    } = event;

    // const allPrivileges =
    //   (privileges?.data as { key: string; value: number }[]) || [];

    const allPrivileges = filteredPrivileges;
    const allIds = allPrivileges.map((p) => p.value);
    const selected = value as number[];

    if (selected.includes(-1)) {
      const isAllSelected = privilegeIds.length === allIds.length;
      const newSelected = isAllSelected ? [] : allIds;

      setPrivilegeIds(newSelected);
      formik.setFieldValue('privileges', newSelected);
    } else {
      setPrivilegeIds(selected);
      formik.setFieldValue('privileges', selected);
    }
  };

   const handlePrivilegeSearchChange = (
      event: React.ChangeEvent<HTMLInputElement>
    ) => {
      setPrivilegeSearchText(event.target.value);
    };

  const handleSystemPriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const price = parseFloat(e.target.value) || 0;
    setSystemPrice(price);
    formik.setFieldValue('systemPrice', price);
    setBalance(price - paidAmount);
  };

  const handlePaidAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const paid = parseFloat(e.target.value) || 0;
    setPaidAmount(paid);
    formik.setFieldValue('totalPaid', paid);
    setBalance(systemPrice - paid);
  };

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={openModel}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('company:title.code')} />
                  <TextField
                    InputProps={{
                      readOnly: data ? true : false,
                    }}
                    autoComplete="off"
                    placeholder={t('company:title.code')}
                    size="small"
                    {...formik.getFieldProps('code')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.name')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.name')}
                    size="small"
                    {...formik.getFieldProps('name')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                {/* image */}

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.isImageEnabled')} />
                  <FormControlLabel
                    control={
                      <Switch
                        checked={formik.values.isImageEnabled}
                        {...formik.getFieldProps('isImageEnabled')}
                        color="primary"
                        onChange={formik.handleChange}
                        sx={{ ml: 0.5 }}
                      />
                    }
                    label={
                      formik.values.isImageEnabled
                        ? t('common:yes')
                        : t('common:no')
                    }
                    sx={{ ml: 0.1, mR: 1 }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.maxUsersAllowed')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.maxUsersAllowed')}
                    size="small"
                    {...formik.getFieldProps('maxUsersAllowed')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.maxBranchAllowed')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.maxBranchAllowed')}
                    size="small"
                    {...formik.getFieldProps('maxBranchAllowed')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.currencyCode')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.currencyCode')}
                    size="small"
                    {...formik.getFieldProps('currencyCode')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.systemPrice')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.systemPrice')}
                    {...formik.getFieldProps('systemPrice')}
                    // value={systemPrice}
                    onChange={handleSystemPriceChange}
                    size="small"
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.totalPaid')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.totalPaid')}
                    {...formik.getFieldProps('totalPaid')}
                    // value={paidAmount}
                    onChange={handlePaidAmountChange}
                    size="small"
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.balance')} />
                  <TextField
                    autoComplete="off"
                    // {...formik.getFieldProps('balance')}
                    onChange={() => formik.setFieldValue('balance', balance)}
                    placeholder={t('company:title.balance')}
                    size="small"
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    value={balance}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader
                    title={t('company:title.maintenanceFeePaidUntil')}
                  />
                  <LocalizationProvider dateAdapter={AdapterDayjs}>
                    <DatePicker
                      InputProps={{ sx: { height: '40px' } }}
                      // maxDate={new Date()}
                      renderInput={(params) => (
                        <TextField
                          sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                          {...params}
                        />
                      )}
                      {...formik.getFieldProps('maintenanceFeePaidUntil')}
                      inputFormat="DD-MM-YYYY"
                      onChange={(date) => {
                        formik.setFieldValue('maintenanceFeePaidUntil', date);
                      }}
                      views={['day', 'month', 'year']}
                    />
                  </LocalizationProvider>
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.maintenanceFee')} />
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={isMonthly}
                        color="primary"
                        onChange={() => handleFeeTypeChange(true)}
                      />
                    }
                    label={t('company:title.monthly')}
                    sx={{ ml: 1 }}
                  />
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={!isMonthly}
                        color="primary"
                        onChange={() => handleFeeTypeChange(false)}
                      />
                    }
                    label={t('company:title.annual')}
                  />
                  <TextField
                    autoComplete="off"
                    onChange={handleMaintenanceFeeChange}
                    placeholder={
                      isMonthly
                        ? t('company:title.maintenanceFeeMonthly')
                        : t('company:title.maintenanceFeeAnnual')
                    }
                    size="small"
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    value={maintenanceFee}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.contactNo')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.contactNo')}
                    size="small"
                    {...formik.getFieldProps('contactNo')}
                    error={
                      formik.touched.contactNo &&
                      (!validateMobileNumber(formik.values.contactNo || '') ||
                        formik.values.contactNo?.length === 0)
                    }
                    helperText={
                      formik.touched.contactNo &&
                      (!validateMobileNumber(formik.values.contactNo || '') ||
                        formik.values.contactNo?.length === 0) && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid mobile number.
                        </span>
                      )
                    }
                    inputProps={{
                      maxLength: 10,
                      type: 'tel',
                    }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.contactPerson')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('company:title.contactPerson')}
                    size="small"
                    {...formik.getFieldProps('contactPerson')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.isEnabled')} />
                  <FormControlLabel
                    control={
                      <Switch
                        checked={formik.values.isEnabled}
                        {...formik.getFieldProps('isEnabled')}
                        color="primary"
                        onChange={formik.handleChange}
                      />
                    }
                    label={
                      formik.values.isEnabled ? t('common:yes') : t('common:no')
                    }
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.usersCount')} />
                  <TextField
                    InputProps={{
                      readOnly: true,
                    }}
                    autoComplete="off"
                    placeholder={t('company:title.usersCount')}
                    size="small"
                    {...formik.getFieldProps('usersCount')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.branchesCount')} />
                  <TextField
                    InputProps={{
                      readOnly: true,
                    }}
                    autoComplete="off"
                    placeholder={t('company:title.branchesCount')}
                    size="small"
                    {...formik.getFieldProps('branchesCount')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('company:title.privileges')} />
                  <FormControl sx={{ width: '100%' }}>
                    <Select
                      input={
                        <OutlinedInput sx={{ height: `${theme.spacing(5)}` }} />
                      }
                      multiple
                      onChange={handleChange}
                      renderValue={(selected) =>
                        selected.length === 0 ? (
                          <em>Placeholder</em>
                        ) : (
                          `${selected.length} of ${
                            ((privileges?.data as Object[]) || []).length
                          } Selected`
                        )
                      }
                      value={privilegeIds}
                    >
                      <MenuItem
                        disableRipple
                        sx={{
                          position: 'sticky',
                          top: 0,
                          backgroundColor: 'white',
                          zIndex: 1,
                          borderBottom: '1px solid #e0e0e0',
                        }}
                        value=""
                      >
                        <TextField
                          InputProps={{
                            startAdornment: (
                              <InputAdornment position="start">
                                <SearchIcon />
                              </InputAdornment>
                            ),
                          }}
                          onChange={handlePrivilegeSearchChange}
                          onClick={(e) => e.stopPropagation()}
                          onKeyDown={(e) => e.stopPropagation()}
                          placeholder="Search privileges..."
                          size="small"
                          sx={{ width: '100%' }}
                          value={privilegeSearchText}
                        />
                      </MenuItem>
                      <MenuItem value={-1}>
                        <Checkbox
                          checked={
                            privilegeIds.length === filteredPrivileges.length
                          }
                        />
                        <ListItemText primary="Select All" />
                      </MenuItem>

                      {filteredPrivileges.map((d) => (
                        <MenuItem
                          key={d.key}
                          value={d.value}
                        >
                          <Checkbox
                            checked={privilegeIds.indexOf(d.value) > -1}
                          />
                          <ListItemText primary={d.key} />
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </GridItem>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
                '&:hover': {
                  // backgroundColor: appColors.carmineRed[20],
                },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={
                !formValid ||
                // Object.keys(formik.touched).length === 0 ||
                isLoading
              }
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewCompany);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
