/* eslint-disable react/jsx-sort-props */
import React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { ICompanyDetailsData } from '../../../core/Interface/company.interface';
import { theme } from '../../../theme';
import { useTranslation } from 'react-i18next';
import {
  formatDate,
  formatTimeToUtc,
  getPriceFormatWithCurrencyCode,
} from '../../../core/utils';
import { appColors } from '../../../theme/appColors';

interface CompanyDataProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: ICompanyDetailsData;
}

const CompanyDetails: React.FC<CompanyDataProps> = ({
  open,
  setOpen,
  data,
}) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { t } = useTranslation(['company']);
  const handleClose = () => {
    setOpen(false);
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      aria-labelledby="company-data-title"
      maxWidth="sm"
      fullWidth
      fullScreen={isMobile}
    >
      <DialogTitle
        id="company-data-title"
        sx={{
          fontWeight: 600,
          background: '#CFD8DC',
          borderRadius: 1,
          padding: '16px 24px',
        }}
      >
        Company Details
      </DialogTitle>
      <DialogContent
        sx={{
          display: 'grid',
          gridTemplateColumns: 'auto 10px auto',
          gap: 1,
          alignItems: 'center',
          padding: '10px 20px',
          mt: 2,
        }}
      >
        {data ? (
          <>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              <strong>{t('company:title.code')}</strong>
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18, textAlign: 'center' }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
            >
              <strong>{data.code}</strong>
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.name')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center' }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.name.length > 14
                ? `${data.name.substring(0, 14)}...`
                : data.name}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.isImageEnabled')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{
                fontSize: 18,
              }}
            >
              {data.isImageEnabled ? 'Yes' : 'No'}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.maxUsersAllowed')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.maxUsersAllowed}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.maxBranchAllowed')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.maxBranchAllowed}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.usersCount')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.usersCount}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.branchesCount')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.branchesCount}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.currencyCode')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.currencyCode}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.maintenanceFee')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {/* {getPriceFormatWithCurrencyCode(data.maintenanceFeeMonthly, data.currencyCode)} */}
              {data.maintenanceFee !== undefined && data.currencyCode ? (
                <>
                  {getPriceFormatWithCurrencyCode(
                    data.maintenanceFee,
                    data.currencyCode
                  )}{' '}
                  {data.isMonthly
                    ? t('company:title.monthly')
                    : t('company:title.annual')}
                </>
              ) : (
                t('company:title.noFee')
              )}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.maintenanceFeePaidUntil')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.maintenanceFeePaidUntil
                ? formatDate(new Date(data.maintenanceFeePaidUntil)) 
                : 'Not Available'}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.contactNo')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.contactNo}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.contactPerson')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.contactPerson}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.isEnabled')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{
                fontSize: 18,
                color:
                  data.isEnabled === true
                    ? appColors.forestGreen[100]
                    : appColors.carmineRed[60],
              }}
            >
              {data.isEnabled ? 'Yes' : 'No'}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.systemPrice')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormatWithCurrencyCode(
                data.systemPrice,
                data.currencyCode
              ) ?? 0}{' '}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.totalPaid')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormatWithCurrencyCode(
                data.totalPaid,
                data.currencyCode
              ) ?? 0}{' '}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('company:title.balance')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {getPriceFormatWithCurrencyCode(
                data.balance,
                data.currencyCode
              ) ?? 0}{' '}
            </Typography>

            {data.createdBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('company:title.createdBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.createdBy}
                </Typography>
              </>
            )}
            {data.updatedBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('company:title.updatedBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.updatedBy}
                </Typography>
              </>
            )}
            {data.createdDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('company:title.createdDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatTimeToUtc(data.createdDate)}
                </Typography>
              </>
            )}
            {data.updatedDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('company:title.updatedDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatTimeToUtc(data.updatedDate)}
                </Typography>
              </>
            )}
          </>
        ) : (
          <Typography variant="body1">No Company data available</Typography>
        )}
      </DialogContent>
      <DialogActions sx={{ padding: '16px 24px' }}>
        <Button
          onClick={handleClose}
          color="primary"
          sx={{
            width: 200,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default CompanyDetails;
