import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import ReminderIcon from '@mui/icons-material/NotificationsActive';
import {
  Button,
  Card,
  CardActions,
  CardContent,
  Grid,
  ListItemButton,
  ListItemIcon,
  Typography,
  Box,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import ReminderPopup from '../../components/ModelPopup/ReminderPopup';
import {
  ICompanyDetails,
  ICompanyDetailsData,
  IPrivilege,
} from '../../core/Interface/company.interface';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import { appColors } from '../../theme/appColors';
import TopInfoSkeleton from '../Dashboard/TopInfoSkeleton';
import { useDeleteCompanyMutation, useGetAllCompanyQuery, useSendPaymentReminderMutation } from '../posApi';
import NewCompany from './components/NewCompany';
import AnimatedPage from '../../layouts/AnimatedPage';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import CompanyDetails from './components/CompanyDetails';
import KeyIcon from '@mui/icons-material/Key';
import PrivilegesDialog from './components/Privileges';
import dayjs from 'dayjs';
import { formatDate } from '../../core/utils';

const Company = () => {
  const { t } = useTranslation(['common', 'usermanage', 'category', 'company']);
  const [companyData, setCompanyData] = React.useState<
    ICompanyDetailsData | undefined
  >();
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [openAddCompany, setOpenAddCompany] = useState(false);
  const [openDeleteCompany, setOpenDeleteCompany] = useState(false);
  const [companyNameToDelete, setCompanyNameToDelete] = useState('');
  const [openReminderPopup, setOpenReminderPopup] = useState(false);
  const [companyNameForReminder, setCompanyNameForReminder] = useState('');
  const [openCompanyDetails, setOpenCompanyDetails] = useState(false);
  const [openPrivilege, setOpenPrivilege] = useState(false);
  const [userPrivilegeData, setUserPrivilegeData] =
    React.useState<IPrivilege[]>();


  const { data, isLoading } = useGetAllCompanyQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const companyList = useMemo(() => {
    return data?.data as ICompanyDetails;
  }, [data?.data]);

  const [deleteCompany] = useDeleteCompanyMutation();
  const [sendPaymentReminder] = useSendPaymentReminderMutation();

  const handleDelete = async (id: string) => {
    try {
      const response = await deleteCompany(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteCompany(false);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleSendReminder = async (id: string) => {
    try {
      const response = await sendPaymentReminder(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenReminderPopup(false);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  return (
    <AnimatedPage>
      <Box data-testid="company">
        <Box sx={{ py: 2 }}>
          <Grid
            container
            display="flex"
            flexDirection="row"
            item
            justifyContent="flex-end"
            key={3}
          >
            {userHasRight(Privileges.CompanyManageAdd) && (
              <Button
                onClick={() => {
                  setCompanyData(undefined);
                  setOpenAddCompany(true);
                }}
                startIcon={<AddIcon />}
                sx={{
                  mr: 2,
                  mb: 0,
                  width: 200,
                  border: 'none',
                  backgroundColor: appColors.darkGreen[20],
                  marginTop: '20px',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  height: '42px',
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: appColors.greyishBlue[20],
                  },
                }}
                variant="outlined"
              >
                {' '}
                {t('category:addCompany')}
              </Button>
            )}
          </Grid>
        </Box>
        {openAddCompany && (
          <NewCompany
            data={companyData}
            handleCloseDialog={() => setOpenAddCompany(false)}
            openModel={openAddCompany}
            title={`${companyData
              ? t('usermanage:editCompany')
              : t('usermanage:addNewCompany')
              } `}
          />
        )}

        {openDeleteCompany && (
          <DeletePopup
            content={`${t(
              'usermanage:confirmMessage'
            )} "${companyNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteCompany(false)}
            onConfirm={async () => {
              await handleDelete(companyData?.id.toString() || '');
            }}
            open={openDeleteCompany}
            title={t('usermanage:deleteUserManage')}
          />
        )}

        {openReminderPopup && (
          <ReminderPopup
            content={`${t(
              'company:confirmMessage'
            )} "${companyNameForReminder}"?`}
            handleCloseReminder={() => setOpenReminderPopup(false)}
            onConfirm={async () => {
              await handleSendReminder(companyData?.id.toString() || '');
            }}
            open={openReminderPopup}
            title={t('company:reminderTitle')}
          />
        )}

        <Grid
          container
          spacing={4}
        >
          {!isLoading &&
            companyList &&
            companyList.records.map((value, index) => (
              <Grid
                item
                key={index}
                md={4}
                xs={12}
              >
                <Card sx={{ p: 0, m: 0, maxWidth: 'fit-content' }}>
                  <CardContent
                    sx={{
                      backgroundColor: value.isEnabled ? '' : '#F4EBEC',
                    }}
                  >
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('category:title.code')}: {value.code}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('category:title.name')}: {value.name}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('company:title.isImageEnabled')}:{' '}
                      {value.isImageEnabled ? 'Yes' : 'No'}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('company:title.usersCount')}: {value.usersCount}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('company:title.branchesCount')}: {value.branchesCount}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('company:title.rootUsername')}: {value.rootUser.username}
                    </Typography>
                    <Typography
                      color="text.secondary"
                      component="div"
                      variant="body2"
                    >
                      {t('company:title.maintenanceFeePaidUntil')}: {''}
                      {value.maintenanceFeePaidUntil
                        ? formatDate(new Date(value.maintenanceFeePaidUntil))
                        : 'Not Available'
                      }
                    </Typography>
                  </CardContent>
                  <CardActions sx={{ cursor: 'pointer', p: 1 }}>
                    <ListItemButton
                      sx={{
                        justifyContent: 'center',
                        cursor: 'pointer',
                      }}
                    >
                      {userHasRight(Privileges.CompanyManageView) &&
                        value.maintenanceFeePaidUntil &&
                        dayjs(value.maintenanceFeePaidUntil).diff(
                          dayjs(),
                          'day'
                        ) <= 14 && (
                          <ListItemIcon
                            onClick={() => {
                              setCompanyData(value);
                              setCompanyNameForReminder(value.name);
                              setOpenReminderPopup(true);
                            }}
                            sx={{
                              display: 'flex',
                              justifyContent: 'center',
                              backgroundColor: appColors.violetGrey[80],
                              py: 1,
                              borderRadius: 2,
                            }}
                          >
                            <ReminderIcon sx={{ color: appColors.white }} />
                          </ListItemIcon>
                        )}
                      {userHasRight(Privileges.CompanyManageView) &&
                        userHasRight(Privileges.CompanyManageView) && (
                          <Box sx={{ pl: 1 }} />
                        )}
                      {userHasRight(Privileges.CompanyManageView) && (
                        <ListItemIcon
                          onClick={() => {
                            setUserPrivilegeData(value.companyPrivileges);
                            setOpenPrivilege(true);
                          }}
                          sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            backgroundColor: appColors.reflexBlue[80],
                            py: 1,
                            borderRadius: 2,
                          }}
                        >
                          <KeyIcon sx={{ color: appColors.white }} />
                        </ListItemIcon>
                      )}
                      {userHasRight(Privileges.CompanyManageView) &&
                        userHasRight(Privileges.CompanyManageEdit) && (
                          <Box sx={{ pl: 1 }} />
                        )}
                      {userHasRight(Privileges.CompanyManageEdit) && (
                        <ListItemIcon
                          onClick={() => {
                            setCompanyData(value);
                            setOpenCompanyDetails(true);
                          }}
                          sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            backgroundColor: appColors.forestGreen[80],
                            py: 1,
                            borderRadius: 2,
                          }}
                        >
                          <FormatListBulletedIcon
                            key={`edit_${value.code}`}
                            sx={{ color: appColors.white }}
                          />
                        </ListItemIcon>
                      )}
                      {userHasRight(Privileges.CompanyManageView) &&
                        userHasRight(Privileges.CompanyManageEdit) && (
                          <Box sx={{ pl: 1 }} />
                        )}
                      {userHasRight(Privileges.CompanyManageEdit) && (
                        <ListItemIcon
                          onClick={() => {
                            setCompanyData(value);
                            setOpenAddCompany(true);
                          }}
                          sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            backgroundColor: appColors.amberYellow[60],
                            py: 1,
                            borderRadius: 2,
                          }}
                        >
                          <EditIcon sx={{ color: appColors.white }} />
                        </ListItemIcon>
                      )}
                      {userHasRight(Privileges.CompanyManageEdit) &&
                        userHasRight(Privileges.CompanyManageDelete) && (
                          <Box sx={{ pl: 1 }} />
                        )}
                      {userHasRight(Privileges.CompanyManageDelete) && (
                        <ListItemIcon
                          onClick={() => {
                            setCompanyData(value);
                            setCompanyNameToDelete(value.name);
                            setOpenDeleteCompany(true);
                          }}
                          sx={{
                            display: 'flex',
                            justifyContent: 'center',
                            backgroundColor: appColors.carmineRed[60],
                            py: 1,
                            borderRadius: 2,
                          }}
                        >
                          <DeleteIcon sx={{ color: appColors.white }} />
                        </ListItemIcon>
                      )}
                    </ListItemButton>
                  </CardActions>
                </Card>
              </Grid>
            ))}
          {isLoading &&
            [1, 2, 3, 4].map((i) => (
              <Grid
                item
                key={i}
                md={4}
                xs={12}
              >
                <TopInfoSkeleton data-testid="top--skeleton" />
              </Grid>
            ))}
          {!isLoading && companyList && companyList.records.length === 0 && (
            <Typography
              align="center"
              data-testid="top-nodata"
              width="100%"
            >
              {t('common:noData')}
            </Typography>
          )}
        </Grid>

        {companyData && openCompanyDetails && (
          <CompanyDetails
            data={companyData}
            open={openCompanyDetails}
            setOpen={setOpenCompanyDetails}
          />
        )}

        {userPrivilegeData && (
          <PrivilegesDialog
            data={userPrivilegeData}
            open={openPrivilege}
            setOpen={setOpenPrivilege}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default Company;
